void exact_attributes(const MeshSnapshot &snapshot,const cgltf_data &file,const color_consumer::Renderer &consumer){
 bool exact=snapshot.ranges.size()==file.meshes_count;float position_error=0;
 for(size_t r=0;r<snapshot.ranges.size();++r){const auto &range=snapshot.ranges[r];const auto &primitive=file.meshes[r].primitives[0];auto colors=color_consumer::attr(primitive.attributes,primitive.attributes_count,cgltf_attribute_type_color),uv=color_consumer::attr(primitive.attributes,primitive.attributes_count,cgltf_attribute_type_texcoord);exact&=colors && uv && range.count==primitive.indices->count && range.material.double_sided==bool(primitive.material->double_sided);if(!exact)break;
  for(size_t c=0;c<range.count;++c){auto n=snapshot.mesh.indices[range.first+c];auto v=cgltf_accessor_read_index(primitive.indices,c);float rgba[4]{},q[2]{};exact&=cgltf_accessor_read_float(colors,v,rgba,4)&&cgltf_accessor_read_float(uv,v,q,2);for(size_t k=0;k<4;++k)exact&=rgba[k]==snapshot.source_colors[n][k];for(size_t k=0;k<2;++k)exact&=q[k]==snapshot.mesh.uv[n][k];position_error=std::max(position_error,length(snapshot.mesh.positions[n]-consumer.world_positions.at(r).at(v)));}
 }
 check(exact && position_error<1e-5f,"Every emitted avatar corner keeps exact source linear RGBA and UV, aligned culling and independently evaluated posed position");
}
