void flat_materials(Scene &scene,uint64_t group){for(const auto &item:scene.objects())if(item.group==group){auto &o=scene.object(item.id);auto b=std::make_shared<SourceMaterialBindings>(*o.material_bindings);auto &m=b->material;for(auto &t:m.textures)t.index=-1;b->roles={};m.textures[2].index=0;b->roles[2].image=image({230,153,204,255});m.parameters.normal_enabled=true;m.parameters.normal_scale=1;m.parameters.base_color={.6f,.4f,.2f,1};m.parameters.shade_color={.1f,.05f,.02f};m.parameters.toony=.5f;m.parameters.shift=-.2f;m.parameters.indirect_intensity=0;m.parameters.light_color_attenuation=0;m.parameters.emission={};m.parameters.rim_color={};m.parameters.outline=MToonOutline::None;m.parameters.cull=MToonCull::Back;m.parameters.scroll={};m.parameters.rotation_speed=0;m.parameters.alpha=MToonAlpha::Mask;m.parameters.alpha_cutoff=.35f;m.parameters.depth_write=true;m.parameters.source_blend=1;m.parameters.destination_blend=0;m.parameters.render_queue=2450;b->validate();o.material_bindings=b;o.material.color=b->native_reference.color;o.material.emissive=b->native_reference.emission;o.material.alpha=Material::AlphaMode::Mask;o.material.alpha_cutoff=.35f;o.material.double_sided=false;}}
